(function(){'use strict';function ready(fn){if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',fn,{once:true});}else{fn();}}ready(function(){var root=document.documentElement;var navToggle=document.getElementById('navToggle');var navMenu=document.getElementById('navMenu');if(navToggle&&navMenu){var setNav=function(open){navToggle.setAttribute('aria-expanded',String(open));navMenu.setAttribute('data-open',String(open));};setNav(false);navToggle.addEventListener('click',function(){setNav(navToggle.getAttribute('aria-expanded')!=='true');});navMenu.addEventListener('keydown',function(event){if(event.key==='Escape'){setNav(false);navToggle.focus();}});document.addEventListener('click',function(event){if(navToggle.getAttribute('aria-expanded')==='true'&&!navMenu.contains(event.target)&&!navToggle.contains(event.target)){setNav(false);}});var wide=window.matchMedia('(min-width:48rem)');var syncWidth=function(mq){if(mq.matches){setNav(false);}};if(typeof wide.addEventListener==='function'){wide.addEventListener('change',syncWidth);}}var searchTrigger=document.getElementById('ssg-search-btn');var themeToggleForSearch=document.getElementById('themeToggle');if(searchTrigger&&themeToggleForSearch&&themeToggleForSearch.parentNode){themeToggleForSearch.parentNode.insertBefore(searchTrigger,themeToggleForSearch.nextSibling);}var shortcutHint=document.querySelector('#ssg-search-btn kbd');if(shortcutHint){var platform=(navigator.userAgentData&&navigator.userAgentData.platform)||navigator.platform||'';var apple=/mac|iphone|ipad|ipod/i.test(platform);shortcutHint.textContent=apple?'\u2318K':'Ctrl K';}var themeToggle=document.getElementById('themeToggle');if(themeToggle){var prefersDark=window.matchMedia('(prefers-color-scheme:dark)');var currentTheme=function(){return(root.getAttribute('data-theme')||(prefersDark.matches?'dark':'light'));};var syncPressed=function(){themeToggle.setAttribute('aria-pressed',String(currentTheme()==='dark'));};syncPressed();themeToggle.addEventListener('click',function(){var next=currentTheme()==='dark'?'light':'dark';root.setAttribute('data-theme',next);try{localStorage.setItem('theme',next);}catch(e){}syncPressed();});if(typeof prefersDark.addEventListener==='function'){prefersDark.addEventListener('change',function(){if(!root.hasAttribute('data-theme')){syncPressed();}});}}});})();